import java.util.*;
public class Solution {
    public int[] sortedSquares(int[] nums) {
        Integer[] r = new Integer[nums.length];
        for (int i = 0; i < nums.length; i++) r[i] = nums[i]*nums[i];
        Arrays.sort(r, (a,b)->a-b);  // O(n log n) boxing + sort
        int[] x = new int[r.length]; for (int i=0;i<r.length;i++) x[i]=r[i]; return x;
    }
}
